fn str_at(xs: List[Str], i: Int) -> Str {
    match xs.get(i) {
        Some(v) => {
            return v
        }
        None => {
            return ""
        }
    }
}

fn contains(xs: List[Str], s: Str) -> Bool {
    for x in xs {
        if x == s {
            return true
        }
    }
    return false
}

fn group_index(gs: List[List[Str]], x: Str) -> Int {
    var i = 0
    for g in gs {
        if contains(g, x) {
            return i
        }
        i = i + 1
    }
    return -1
}

fn add_to(gs: List[List[Str]], idx: Int, x: Str) -> List[List[Str]] {
    var out: List[List[Str]] = []
    var i = 0
    for g in gs {
        if i == idx {
            out = out.push(g.push(x))
        } else {
            out = out.push(g)
        }
        i = i + 1
    }
    return out
}

fn merge_at(gs: List[List[Str]], i: Int, j: Int) -> List[List[Str]] {
    var gi: List[Str] = []
    var gj: List[Str] = []
    var k = 0
    for g in gs {
        if k == i {
            gi = g
        }
        if k == j {
            gj = g
        }
        k = k + 1
    }
    var merged = gi
    for x in gj {
        if not contains(merged, x) {
            merged = merged.push(x)
        }
    }
    var out: List[List[Str]] = []
    k = 0
    for g in gs {
        if k == i {
            out = out.push(merged)
        } else if k != j {
            out = out.push(g)
        }
        k = k + 1
    }
    return out
}

fn insert_str(xs: List[Str], x: Str) -> List[Str] {
    var out: List[Str] = []
    var placed = false
    for y in xs {
        if not placed and y > x {
            out = out.push(x)
            placed = true
        }
        out = out.push(y)
    }
    if not placed {
        out = out.push(x)
    }
    return out
}

fn sort_strs(xs: List[Str]) -> List[Str] {
    var out: List[Str] = []
    for x in xs {
        out = insert_str(xs: out, x: x)
    }
    return out
}

fn insert_group(xs: List[List[Str]], g: List[Str]) -> List[List[Str]] {
    var out: List[List[Str]] = []
    var placed = false
    let gk = str_at(g, 0)
    for h in xs {
        if not placed and str_at(h, 0) > gk {
            out = out.push(g)
            placed = true
        }
        out = out.push(h)
    }
    if not placed {
        out = out.push(g)
    }
    return out
}

pub fn groups(pairs: List[List[Str]]) -> List[List[Str]] {
    var gs: List[List[Str]] = []
    for p in pairs {
        let a = str_at(p, 0)
        let b = str_at(p, 1)
        let ia = group_index(gs, a)
        let ib = group_index(gs, b)
        if ia < 0 and ib < 0 {
            var g: List[Str] = [a]
            if a != b {
                g = g.push(b)
            }
            gs = gs.push(g)
        } else if ia >= 0 and ib < 0 {
            gs = add_to(gs: gs, idx: ia, x: b)
        } else if ia < 0 and ib >= 0 {
            gs = add_to(gs: gs, idx: ib, x: a)
        } else if ia != ib {
            gs = merge_at(gs: gs, i: ia, j: ib)
        }
    }

    var result: List[List[Str]] = []
    for g in gs {
        result = insert_group(result, sort_strs(g))
    }
    return result
}
